   SELECT COALESCE(
    EXISTS(
        SELECT 1
        FROM payroll
        WHERE month = #{month}
        AND year = #{year}
    ),
    false
)

      SELECT *
FROM employee e
WHERE NOT EXISTS (
    SELECT 1
    FROM payroll p
    WHERE p.employee_id = e.id
    AND p.month = #{month}
    AND p.year = #{year}
);

  SELECT id
FROM payroll
WHERE employee_id = #{employeeId}
AND month = #{month}
AND year = #{year}
